"""Simple, obviously-correct reference model (dict based) for cross-checking."""
import json

MAXVAR = 4611686018427387903

class Err(Exception):
    def __init__(self, code, frame=None):
        self.code = code; self.frame = frame

class S:
    def __init__(self):
        self.highest = 0; self.final_size = None; self.reset = False; self.stopped = False
        self.data = {}   # offset -> byte value
        self.delivered = bytearray()

class C:
    def __init__(self):
        self.highest = 0; self.data = {}
        self.contig = bytearray()

def store_bytes(data, offset, payload, policy):
    """returns new dict or raises Err(PROTOCOL_VIOLATION)"""
    new = dict(data)
    for i, b in enumerate(payload):
        o = offset + i
        if o in new:
            if new[o] != b:
                if policy == "reject":
                    raise Err("PROTOCOL_VIOLATION")
                # first wins: keep
            else:
                pass
        else:
            new[o] = b
    return new

def contiguous(data):
    out = bytearray(); o = 0
    while o in data:
        out.append(data[o]); o += 1
    return out

def allowed(level, fr):
    t = fr["type"]
    if t in ("PADDING","PING"): return True
    if t in ("ACK","CRYPTO"): return level in ("I","H","A")
    if t in ("STREAM","RESET_STREAM","STOP_SENDING"): return level in ("Z","A")
    if t == "CLOSE": return (level in ("Z","A")) if fr["app"] else True
    return False

def contains(sent, lo, hi):
    pos = lo
    for s, e in sent:
        if e < pos: continue
        if s > pos: return False
        if e >= hi: return True
        pos = e + 1
    return False

def replay(doc):
    results = []
    for tr in doc["traces"]:
        cfg = tr["config"]; events = tr["events"]
        keys = {"I":"live","H":"absent","Z":("live" if cfg["early"] else "absent"),"A":"absent"}
        queue = []
        streams = {}
        crypto = {"I":C(),"H":C(),"A":C()}
        total = 0
        pns = {"I":set(),"H":set(),"A":set()}
        state = "open"; code=None; at_ms=None; source=None; peer_code=None; last=0
        res = {}
        def rec(e,p,st,rs,t,f): res[(e,p)] = {"event":e,"packet":p,"status":st,"reason":rs,"at_ms":t,"frame":f}
        def terminate(newstate, c, t, src, pc):
            nonlocal state, code, at_ms, source, peer_code
            state=newstate; code=c; at_ms=t; source=src; peer_code=pc
            for q in list(queue):
                rec(q[0],q[1],"dropped","CONNECTION_CLOSED",t,None)
            queue.clear()
        def do_packet(e,p,frames,level,pn,auth,t,size,from_queue):
            if not from_queue and level=="I" and size < 1200:
                rec(e,p,"dropped","INITIAL_TOO_SMALL",t,None); return
            if level=="Z" and not cfg["early"]:
                rec(e,p,"dropped","EARLY_REJECTED",t,None); return
            if keys[level]=="discarded":
                rec(e,p,"dropped","KEYS_DISCARDED",t,None); return
            if keys[level]=="absent":
                if len(queue) < cfg["buffer_packets"]:
                    queue.append((e,p,level,pn,auth,frames,t))
                else:
                    rec(e,p,"dropped","BUFFER_FULL",t,None)
                return
            if not auth:
                rec(e,p,"dropped","AUTH",t,None); return
            space = "A" if level in ("Z","A") else level
            if pn in pns[space]:
                rec(e,p,"duplicate","DUPLICATE",t,None); return
            # frames
            if not frames:
                terminate("closed","FRAME_ENCODING_ERROR",t,{"event":e,"packet":p,"frame":None},None)
                rec(e,p,"error","FRAME_ENCODING_ERROR",t,None); return
            for i,fr in enumerate(frames):
                if fr["type"]=="UNKNOWN":
                    terminate("closed","FRAME_ENCODING_ERROR",t,{"event":e,"packet":p,"frame":i},None)
                    rec(e,p,"error","FRAME_ENCODING_ERROR",t,i); return
                if not allowed(level,fr):
                    terminate("closed","PROTOCOL_VIOLATION",t,{"event":e,"packet":p,"frame":i},None)
                    rec(e,p,"error","PROTOCOL_VIOLATION",t,i); return
            # semantic: work on copies, commit at the end
            s_copy = {k: S() for k in streams}
            for k,v in streams.items():
                s_copy[k] = S(); s_copy[k].highest=v.highest; s_copy[k].final_size=v.final_size
                s_copy[k].reset=v.reset; s_copy[k].stopped=v.stopped; s_copy[k].data=dict(v.data)
                s_copy[k].delivered=bytearray(v.delivered)
            c_copy = {k: C() for k in crypto}
            for k,v in crypto.items():
                c_copy[k]=C(); c_copy[k].highest=v.highest; c_copy[k].data=dict(v.data); c_copy[k].contig=bytearray(v.contig)
            tot_copy = total
            def check_stream_dir(sid):
                if sid % 4 not in (0,2): raise Err("STREAM_STATE_ERROR")
                lim = cfg["max_streams_bidi"] if sid%4==0 else cfg["max_streams_uni"]
                if sid//4+1 > lim: raise Err("STREAM_LIMIT_ERROR")
            try:
                for i,fr in enumerate(frames):
                    t_ = fr["type"]
                    if t_ in ("PADDING","PING"): continue
                    if t_=="ACK":
                        rr = fr["ranges"]
                        if not rr: raise Err("FRAME_ENCODING_ERROR")
                        prev=None
                        for lo,hi in rr:
                            if lo>hi: raise Err("FRAME_ENCODING_ERROR")
                            if prev is not None and lo<=prev+1: raise Err("FRAME_ENCODING_ERROR")
                            prev=hi
                        sent = cfg["sent"][level]
                        for lo,hi in rr:
                            if not contains(sent,lo,hi): raise Err("PROTOCOL_VIOLATION")
                        continue
                    if t_=="CRYPTO":
                        payload = bytes.fromhex(fr["data_hex"]); off=fr["offset"]; end=off+len(payload)
                        if end > MAXVAR: raise Err("FRAME_ENCODING_ERROR")
                        if end > cfg["crypto_limit"]: raise Err("CRYPTO_BUFFER_EXCEEDED")
                        c = c_copy[level]
                        c.data = store_bytes(c.data, off, payload, cfg["overlap"])
                        if end > c.highest: c.highest = end
                        c.contig = contiguous(c.data)
                        continue
                    if t_=="STREAM":
                        sid=fr["id"]; off=fr["offset"]; payload=bytes.fromhex(fr["data_hex"]); fin=fr["fin"]
                        check_stream_dir(sid)
                        st = s_copy.get(sid)
                        if st is None:
                            st = S(); s_copy[sid]=st
                        end = off+len(payload)
                        if end > MAXVAR: raise Err("FRAME_ENCODING_ERROR")
                        if st.final_size is not None and (end > st.final_size or (fin and end != st.final_size)):
                            raise Err("FINAL_SIZE_ERROR")
                        if fin and end < st.highest: raise Err("FINAL_SIZE_ERROR")
                        if end > cfg["max_stream_data"]: raise Err("FLOW_CONTROL_ERROR")
                        nh = max(st.highest,end); delta = nh - st.highest
                        if tot_copy + delta > cfg["max_data"]: raise Err("FLOW_CONTROL_ERROR")
                        if not st.reset:
                            st.data = store_bytes(st.data, off, payload, cfg["overlap"])
                        st.highest = nh; tot_copy += delta
                        if fin and st.final_size is None: st.final_size = end
                        if not st.reset:
                            newcontig = contiguous(st.data)
                            if len(newcontig) > len(st.delivered):
                                st.delivered = newcontig
                        continue
                    if t_=="RESET_STREAM":
                        sid=fr["id"]; size=fr["final_size"]
                        check_stream_dir(sid)
                        st = s_copy.get(sid)
                        if st is None:
                            st = S(); s_copy[sid]=st
                        if st.final_size is not None and st.final_size != size: raise Err("FINAL_SIZE_ERROR")
                        if size < st.highest: raise Err("FINAL_SIZE_ERROR")
                        if size > cfg["max_stream_data"]: raise Err("FLOW_CONTROL_ERROR")
                        nh=max(st.highest,size); delta=nh-st.highest
                        if tot_copy + delta > cfg["max_data"]: raise Err("FLOW_CONTROL_ERROR")
                        st.highest=nh; tot_copy+=delta; st.final_size=size; st.reset=True
                        continue
                    if t_=="STOP_SENDING":
                        sid=fr["id"]
                        if sid%4 != 0: raise Err("STREAM_STATE_ERROR")
                        if sid//4+1 > cfg["max_streams_bidi"]: raise Err("STREAM_LIMIT_ERROR")
                        st = s_copy.get(sid)
                        if st is None:
                            st = S(); s_copy[sid]=st
                        st.stopped=True
                        continue
                    if t_=="CLOSE":
                        # commit everything so far
                        streams.clear(); streams.update(s_copy)
                        crypto.clear(); crypto.update(c_copy)
                        globals()  # noop
                        return ("close", fr["app"], fr["code"], i)
                    raise Err("PROTOCOL_VIOLATION")
            except Err as er:
                terminate("closed", er.code, t, {"event":e,"packet":p,"frame":er.frame if er.frame is not None else i}, None)
                rec(e,p,"error",er.code,t, er.frame if er.frame is not None else i)
                return
            # commit
            streams.clear(); streams.update(s_copy)
            crypto.clear(); crypto.update(c_copy)
            globals()['total'] = tot_copy
            return None
        # fix total handling: use a mutable holder
        return None
